insert into public.faqs (id, treatment_slug, city_slug, position, question, answer, published) values
  ('faq-what', 'gynecomastia-surgery', null, 1, 'What is gynecomastia?', 'It is growth of breast gland tissue in boys and men, on one side or both. The chest can also look full because of fat alone. Doctors call that pseudogynecomastia, and many men have a mix of the two.', true),
  ('faq-symptoms', 'gynecomastia-surgery', null, 2, 'What are the signs, and which need a doctor soon?', 'A firm disc behind the nipple, uneven swelling, tenderness and a wider areola are the usual signs. A hard lump, change on one side only, pain or fluid from the nipple should be seen by a doctor early, before you think about surgery.', true),
  ('faq-candidate', 'gynecomastia-surgery', null, 3, 'Who is a suitable candidate for surgery?', 'Surgeons look for good general health, a steady weight, a chest that has stopped changing, and a reason that matters to you. Smokers are usually asked to stop. A surgeon decides after an examination, not from a photo.', true),
  ('faq-anaesthesia', 'gynecomastia-surgery', null, 4, 'Is gynecomastia surgery done under general or local anaesthesia?', 'Smaller operations can be done under local anaesthesia with sedation. Larger operations, or gland removal together with liposuction, usually use general anaesthesia. The surgeon and the anaesthetist decide after your examination and a fitness check.', true),
  ('faq-work', 'gynecomastia-surgery', null, 5, 'How many days off work do I need?', 'Many people return to desk work after about a week, and some need longer. Driving is usually after about two weeks and chest training after six weeks or more. These are typical timings, not promises, and your surgeon sets yours. The [recovery guide](/gynecomastia-surgery#recovery) shows the full pattern week by week.', true),
  ('faq-scar', 'gynecomastia-surgery', null, 6, 'Will I have visible scars?', 'Yes, some mark remains. For gland removal the cut is usually small and sits at the edge of the areola, where the skin colour changes, or at the side of the chest. Liposuction leaves tiny marks. Larger cases with loose skin may need longer scars. Scars start red and usually fade over a year or more. Ask the surgeon to mark the planned cuts on your chest.', true),
  ('faq-sameday', 'gynecomastia-surgery', 'gurgaon', 7, 'Can I go home to Delhi, Noida or Faridabad the same day?', 'After a day-care operation many people go home the same day, but you should not drive yourself. Bring an attendant, and plan the ride so you are not stuck in traffic for hours on day one. The surgeon and the anaesthetist decide whether you stay a night.', true),
  ('faq-insurance', 'gynecomastia-surgery', null, 8, 'Does insurance cover gynecomastia surgery?', 'Usually not, because most policies treat it as cosmetic. Some may consider it when a doctor records a medical need. Ask your insurer in writing before you book, and ask the hospital which diagnosis and procedure it will put on the estimate.', true),
  ('faq-name', 'gynecomastia-surgery', 'gurgaon', 9, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Gurgaon and Gurugram are the same city in Haryana, and both spellings are in common use. This page uses Gurgaon because more people search for it.', true),
  ('faq-centre', 'gynecomastia-surgery', 'gurgaon', 10, 'What kind of place is the operation done in?', 'A partner day-care surgical centre or a hospital, depending on the plan. We do not name it on this page. The [checks](#facilities) listed above apply to either.', true),
  ('faq-summer', 'gynecomastia-surgery', 'gurgaon', 11, 'Does the heat of a Gurgaon summer matter for recovery?', 'It can. A compression vest is worn under clothes for weeks, and it is uncomfortable in heat. Ask for a breathable garment and a spare, and plan the first week indoors with air conditioning if you can.', true),
  ('faq-return', 'gynecomastia-surgery', null, 12, 'Can the enlargement come back?', 'It can. Weight gain, anabolic steroids, some medicines, alcohol and some medical conditions can cause new enlargement. Read about the [possible causes](/learn/gynecomastia-causes), and if the cause is still there, tell the surgeon before you decide.', true),
  ('faq-myth', 'gynecomastia-surgery', null, 13, 'Can creams, oils or supplements remove it?', 'There is no good evidence that creams, oils, homeopathy or fat-burner supplements remove gland tissue. Fat may shrink with weight loss, gland usually does not. Chest exercise builds muscle and can make a gland look more prominent.', true),
  ('faq-second', 'gynecomastia-surgery', null, 14, 'What if I need a second operation?', 'It happens. Ask the hospital, in writing, whether a second operation is charged and for how long after the first. You can [compare two quotes](/learn/how-to-compare-surgery-quotes) on exactly this line.', true)
