insert into public.videos (slug, title, duration, iso_duration, description, transcript, poster, poster_alt, youtube_id, upload_date, is_sample, published) values
  ('gynecomastia-explained', 'Gynecomastia explained: grades, causes and when to see a doctor', '4:30', 'PT4M30S', 'A short sample video on how doctors describe the grades of gynecomastia, common causes, and when to see a doctor.', 'Gynecomastia is growth of breast gland tissue in boys and men. Doctors describe the size on a four-point scale. Some cases settle on their own, especially in teenagers. Others are linked to medicines or weight change. Only an examination can tell gland from fat. See a doctor early if there is a hard lump, one-sided change, pain or discharge.', 'grades', 'Animated chest diagram showing the four grades', null, '2026-11-09', true, true),
  ('gynecomastia-recovery-weeks', 'Recovery week by week: what to expect after chest surgery', '5:10', 'PT5M10S', 'A short sample video on what most people notice and do in each week after chest surgery, from day one to week twelve.', 'Day one is for rest at home with a compression garment on. Swelling and bruising peak in the first week and ease in the second. Many people return to desk work after about a week. Driving usually follows at about two weeks, and chest training after six weeks or more, if the surgeon agrees. Swelling takes months to settle.', 'recovery', 'Calendar graphic with weeks 1 to 12 marked', null, '2026-11-09', true, true)
